	public const string Common = "struct ObjectData {\n    float4x4 model; float4 normal0; float4 normal1; float4 normal2;\n    float4 baseColor; float4 emissive; float4 surface; float4 coat; float4 flags; float4 cut; float4 bands[16];\n};\nStructuredBuffer<ObjectData> objects : register(t8);\n\nstruct VertexIn {\n    float3 position : POSITION; float3 normal : NORMAL; float2 uv : TEXCOORD0; float4 color : COLOR0; uint item : ITEM;\n};\nstruct VertexOut {\n    float4 position : SV_Position;\n    float3 world : TEXCOORD0; float3 normal : TEXCOORD1; float2 uv : TEXCOORD2; float4 color : COLOR0;\n    nointerpolation uint item : ITEM;\n};\n\nfloat3 transformNormal(ObjectData o, float3 n) {\n    return normalize(o.normal0.xyz * n.x + o.normal1.xyz * n.y + o.normal2.xyz * n.z);\n}\n\nfloat3 sRGBFromLinear(float3 value) {\n    float3 v = max(value, 0.0);\n    return lerp(pow(v, 0.41666) * 1.055 - 0.055, value * 12.92, (float3)(value <= 0.0031308));\n}\n\nstatic const float PI = 3.14159265358979;\nstatic const float INV_PI = 0.3183098861837907;";

	public const string Marker = "struct ObjectData {\n    float4x4 model; float4 normal0; float4 normal1; float4 normal2;\n    float4 baseColor; float4 emissive; float4 surface; float4 coat; float4 flags; float4 cut; float4 bands[16];\n};\nStructuredBuffer<ObjectData> objects : register(t8);\n\nstruct VertexIn {\n    float3 position : POSITION; float3 normal : NORMAL; float2 uv : TEXCOORD0; float4 color : COLOR0; uint item : ITEM;\n};\nstruct VertexOut {\n    float4 position : SV_Position;\n    float3 world : TEXCOORD0; float3 normal : TEXCOORD1; float2 uv : TEXCOORD2; float4 color : COLOR0;\n    nointerpolation uint item : ITEM;\n};\n\nfloat3 transformNormal(ObjectData o, float3 n) {\n    return normalize(o.normal0.xyz * n.x + o.normal1.xyz * n.y + o.normal2.xyz * n.z);\n}\n\nfloat3 sRGBFromLinear(float3 value) {\n    float3 v = max(value, 0.0);\n    return lerp(pow(v, 0.41666) * 1.055 - 0.055, value * 12.92, (float3)(value <= 0.0031308));\n}\n\nstatic const float PI = 3.14159265358979;\nstatic const float INV_PI = 0.3183098861837907;\ncbuffer Frame : register(b0) { float4x4 viewProjection; float4 eye; float4 style; };\n\nVertexOut davinci_vertex(VertexIn v) {\n    ObjectData o = objects[v.item];\n    float4 world = mul(o.model, float4(v.position, 1.0));\n    VertexOut r;\n    r.position = mul(viewProjection, world);\n    r.world = world.xyz;\n    r.normal = transformNormal(o, v.normal);\n    r.uv = v.uv;\n    r.color = v.color;\n    r.item = v.item;\n    return r;\n}\n\nfloat D_GGX(float alpha, float dotNH) {\n    float a2 = alpha * alpha;\n    float d = dotNH * dotNH * (a2 - 1.0) + 1.0;\n    return INV_PI * a2 / (d * d);\n}\nfloat V_GGX_SmithCorrelated(float alpha, float dotNL, float dotNV) {\n    float a2 = alpha * alpha;\n    float gv = dotNL * sqrt(a2 + (1.0 - a2) * dotNV * dotNV);\n    float gl = dotNV * sqrt(a2 + (1.0 - a2) * dotNL * dotNL);\n    return 0.5 / max(gv + gl, 1e-6);\n}\nfloat3 F_Schlick(float3 f0, float f90, float dotVH) {\n    float fresnel = exp2((-5.55473 * dotVH - 6.98316) * dotVH);\n    return f0 * (1.0 - fresnel) + f90 * fresnel;\n}\nfloat3 BRDF_GGX(float3 l, float3 v, float3 n, float3 specularColor, float roughness) {\n    float alpha = roughness * roughness;\n    float3 h = normalize(l + v);\n    float dotNL = saturate(dot(n, l)), dotNV = saturate(dot(n, v)), dotNH = saturate(dot(n, h)), dotVH = saturate(dot(v, h));\n    return F_Schlick(specularColor, 1.0, dotVH) * (V_GGX_SmithCorrelated(alpha, dotNL, dotNV) * D_GGX(alpha, dotNH));\n}\n\nfloat4 davinci_fragment(VertexOut i, bool isFrontFacing : SV_IsFrontFace) : SV_Target {\n    ObjectData o = objects[i.item];\n    float3 normal = normalize(i.normal);\n    if (o.flags.y > 0.5) {\n        normal = normalize(cross(ddx(i.world), ddy(i.world)));\n        if (dot(normal, eye.xyz - i.world) < 0.0) normal = -normal;\n    } else if (o.flags.z > 0.5 && !isFrontFacing) {\n        normal = -normal;\n    }\n    float4 base = o.baseColor;\n    if (o.flags.x > 0.5) base.rgb *= i.color.rgb;\n    int bandCount = (int)o.surface.w;\n    if (bandCount > 0) {\n        int band = clamp((int)floor((1.0 - i.uv.y) * (float)bandCount), 0, bandCount - 1);\n        base.rgb *= o.bands[band].rgb;\n    }\n    float metalness = o.surface.y;\n    float3 diffuseColor = base.rgb * (1.0 - metalness);\n    float3 specularColor = lerp((float3)0.04, base.rgb, metalness);\n    float3 geometryNormal = normalize(i.normal);\n    float3 variation = max(abs(ddx(geometryNormal)), abs(ddy(geometryNormal)));\n    float roughness = min(max(o.surface.x, 0.0525) + max(max(variation.x, variation.y), variation.z), 1.0);\n\n    float3 viewDirection = normalize(eye.xyz - i.world);\n    if (style.x > 0.5) {\n        // Clicky's illustrated look: flat colour where the light falls, one cool darker tone where it does not.\n        float3 light = normalize(style.yzw);\n        float facing = dot(normal, light);\n        float lit = smoothstep(-0.08, 0.14, facing);\n        float3 colour = base.rgb;\n        float3 shade = colour * lerp(float3(0.50, 0.53, 0.66), float3(0.30, 0.32, 0.42), metalness);\n        float3 tone = lerp(shade, colour, lit);\n        tone *= lerp(0.86, 1.0, smoothstep(-0.75, -0.35, facing));\n        float3 halfway = normalize(light + viewDirection);\n        float shininess = saturate(1.0 - o.surface.x);\n        float highlight = smoothstep(0.985 - 0.06 * metalness - 0.03 * (1.0 - shininess), 0.995 - 0.06 * metalness, dot(normal, halfway));\n        tone = lerp(tone, (float3)1.0, highlight * (0.35 + 0.55 * shininess));\n        tone += o.emissive.rgb;\n        return float4(sRGBFromLinear(tone), base.a * o.surface.z);\n    }\n    float3 sky = (float3)1.2;\n    float3 ground = float3(0.04231, 0.06124, 0.09758) * 1.2;\n    float3 irradiance = lerp(ground, sky, 0.5 * normal.y + 0.5);\n    float3 outgoing = irradiance * diffuseColor * INV_PI;\n    float3 directions[2] = { normalize(float3(3.0, 5.0, 4.0)), normalize(float3(-4.0, 2.0, -4.0)) };\n    float3 colors[2] = { (float3)2.2, float3(0.34670, 0.55201, 1.0) * 0.9 };\n    [unroll] for (int k = 0; k < 2; k++) {\n        float dotNL = saturate(dot(normal, directions[k]));\n        float3 lightIrradiance = dotNL * colors[k];\n        outgoing += lightIrradiance * diffuseColor * INV_PI;\n        outgoing += lightIrradiance * BRDF_GGX(directions[k], viewDirection, normal, specularColor, roughness);\n    }\n    outgoing += o.emissive.rgb;\n    return float4(sRGBFromLinear(outgoing), base.a * o.surface.z);\n}\n\n// ---------------------------------------------------------------- ids for the ink outline and picking\n\nuint davinci_uncut_id_fragment(VertexOut i) : SV_Target {\n    return i.item + 1u;\n}\n\n// A cut part's ids stop at its cut, and what shows through the opening gets an id of its own.\nuint davinci_picking_fragment(VertexOut i, bool isFrontFacing : SV_IsFrontFace) : SV_Target {\n    ObjectData o = objects[i.item];\n    uint identifier = i.item + 1u;\n    if (dot(o.cut.xyz, o.cut.xyz) > 0.25) {\n        if (dot(i.world, o.cut.xyz) > o.cut.w) discard;\n        if (!isFrontFacing && o.flags.z < 0.5) return identifier | 0x80000000u;\n    }\n    return identifier;\n}\n\n// ---------------------------------------------------------------- the ink outline (a full-screen triangle)\n\ncbuffer Outline : register(b1) {\n    float4 inkColor; float halfWidth; float seamHalfWidth; float seamStrength; float seamShade;\n    uint neighbourCount; uint readsClear; float2 outlinePad;\n    float4 neighbours[80];\n};\nTexture2D<uint> opaqueIDs : register(t0);\nTexture2D<uint> clearIDs : register(t1);\n\nfloat4 davinci_outline_vertex(uint vid : SV_VertexID) : SV_Position {\n    float2 corner = float2(vid == 1 ? 3.0 : -1.0, vid == 2 ? 3.0 : -1.0);\n    return float4(corner, 0.0, 1.0);\n}\n\n// How far (pixels) the nearest change of part id is, against nothing (x) and between parts (y).\nfloat2 nearestEdges(int2 p) {\n    uint w, h;\n    opaqueIDs.GetDimensions(w, h);\n    int2 size = int2(w, h);\n    uint a = opaqueIDs.Load(int3(p, 0)), b = readsClear != 0u ? clearIDs.Load(int3(p, 0)) : 0u;\n    float2 nearest = (float2)1e9;\n    uint index = 0;\n    [loop] for (; index + 4 <= neighbourCount; index += 4) {\n        uint4 opaque, clear = (uint4)b;\n        float4 distances;\n        [unroll] for (uint lane = 0; lane < 4; lane++) {\n            float4 neighbour = neighbours[index + lane];\n            int2 q = clamp(p + int2(neighbour.xy), int2(0, 0), size - 1);\n            opaque[lane] = opaqueIDs.Load(int3(q, 0));\n            if (readsClear != 0u) clear[lane] = clearIDs.Load(int3(q, 0));\n            distances[lane] = neighbour.z;\n        }\n        bool4 changed = (opaque != a) || (clear != b);\n        bool4 silhouette = (opaque == 0u) != (a == 0u);\n        float4 outside = (changed && silhouette) ? distances : (float4)1e9;\n        float4 inside = (changed && !silhouette) ? distances : (float4)1e9;\n        nearest = min(nearest, float2(min(min(outside.x, outside.y), min(outside.z, outside.w)),\n                                      min(min(inside.x, inside.y), min(inside.z, inside.w))));\n    }\n    [loop] for (; index < neighbourCount; index++) {\n        float4 neighbour = neighbours[index];\n        int2 q = clamp(p + int2(neighbour.xy), int2(0, 0), size - 1);\n        uint qa = opaqueIDs.Load(int3(q, 0)), qb = readsClear != 0u ? clearIDs.Load(int3(q, 0)) : 0u;\n        if (qa != a || qb != b) {\n            if ((qa == 0u) != (a == 0u)) nearest.x = min(nearest.x, neighbour.z);\n            else nearest.y = min(nearest.y, neighbour.z);\n        }\n    }\n    return nearest;\n}\n\nfloat4 davinci_outline_fragment(float4 position : SV_Position) : SV_Target {\n    float2 nearest = nearestEdges(int2(position.xy));\n    float coverage = max(saturate(halfWidth - nearest.x + 1.0), seamStrength * saturate(seamHalfWidth - nearest.y + 1.0));\n    return inkColor * coverage;\n}\n\n// The outline in ink and the seams in a shade of each part's own colour, in one pass (dual-source blending:\n// colour = ink * shade + what is there * (1 - ink's alpha) * shade).\nstruct InkAndSeam { float4 color : SV_Target0; float4 factor : SV_Target1; };\nInkAndSeam davinci_ink_and_seam_fragment(float4 position : SV_Position) {\n    float2 nearest = nearestEdges(int2(position.xy));\n    float4 ink = inkColor * saturate(halfWidth - nearest.x + 1.0);\n    float shade = 1.0 - seamStrength * saturate(seamHalfWidth - nearest.y + 1.0) * (1.0 - seamShade);\n    InkAndSeam r;\n    r.color = float4(ink.rgb * shade, ink.a);\n    r.factor = float4((float3)((1.0 - ink.a) * shade), 1.0 - ink.a);\n    return r;\n}";

	public const string Studio = "struct ObjectData {\n    float4x4 model; float4 normal0; float4 normal1; float4 normal2;\n    float4 baseColor; float4 emissive; float4 surface; float4 coat; float4 flags; float4 cut; float4 bands[16];\n};\nStructuredBuffer<ObjectData> objects : register(t8);\n\nstruct VertexIn {\n    float3 position : POSITION; float3 normal : NORMAL; float2 uv : TEXCOORD0; float4 color : COLOR0; uint item : ITEM;\n};\nstruct VertexOut {\n    float4 position : SV_Position;\n    float3 world : TEXCOORD0; float3 normal : TEXCOORD1; float2 uv : TEXCOORD2; float4 color : COLOR0;\n    nointerpolation uint item : ITEM;\n};\n\nfloat3 transformNormal(ObjectData o, float3 n) {\n    return normalize(o.normal0.xyz * n.x + o.normal1.xyz * n.y + o.normal2.xyz * n.z);\n}\n\nfloat3 sRGBFromLinear(float3 value) {\n    float3 v = max(value, 0.0);\n    return lerp(pow(v, 0.41666) * 1.055 - 0.055, value * 12.92, (float3)(value <= 0.0031308));\n}\n\nstatic const float PI = 3.14159265358979;\nstatic const float INV_PI = 0.3183098861837907;\n#ifndef STUDIO_MAY_CUT\n#define STUDIO_MAY_CUT 1\n#endif\ncbuffer Frame : register(b0) {\n    float4x4 viewProjection; float4x4 lightViewProjection; float4 eye;\n    float4 key; float4 keyColor; float4 rim; float4 rimColor; float4 environment; float4 shadow; float4 ground; float4 groundColor;\n    float4 occlusion; float4 target; float4 viewForward; float4 rayBase; float4 rayStepX; float4 rayStepY; float4 grade;\n    float4 cutHatch;\n};\n\nTextureCube<float4> environmentMap : register(t0);\nTextureCube<float4> irradianceMap : register(t1);\nTexture2D<float> shadowMap : register(t2);\nTexture2D<float> occlusionMap : register(t3);\nTexture2D<float> occlusionDistances : register(t4);\nSamplerState environmentSampler : register(s0);\nSamplerComparisonState shadowSampler : register(s1);\nSamplerState pointClamp : register(s2);\n\nVertexOut studio_vertex(VertexIn v) {\n    ObjectData o = objects[v.item];\n    float4 world = mul(o.model, float4(v.position, 1.0));\n    VertexOut r;\n    r.position = mul(viewProjection, world);\n    r.world = world.xyz;\n    r.normal = transformNormal(o, v.normal);\n    r.uv = v.uv;\n    r.color = v.color;\n    r.item = v.item;\n    return r;\n}\n\nfloat4 studio_shadow_vertex(VertexIn v) : SV_Position {\n    ObjectData o = objects[v.item];\n    return mul(lightViewProjection, mul(o.model, float4(v.position, 1.0)));\n}\n\n// A cut part's shadow: only the half that is still there.\nstruct ShadowOut { float4 position : SV_Position; float3 world : TEXCOORD0; nointerpolation uint item : ITEM; };\nShadowOut studio_shadow_cut_vertex(VertexIn v) {\n    ObjectData o = objects[v.item];\n    float4 world = mul(o.model, float4(v.position, 1.0));\n    ShadowOut r;\n    r.position = mul(lightViewProjection, world);\n    r.world = world.xyz;\n    r.item = v.item;\n    return r;\n}\nvoid studio_shadow_cut_fragment(ShadowOut i) {\n    ObjectData o = objects[i.item];\n    if (dot(i.world, o.cut.xyz) > o.cut.w) discard;\n}\n\n// ---------------------------------------------------------------- ambient occlusion\nfloat studio_distance_fragment(VertexOut i) : SV_Target {\n    ObjectData o = objects[i.item];\n    if (dot(o.cut.xyz, o.cut.xyz) > 0.25 && dot(i.world, o.cut.xyz) > o.cut.w) discard;\n    return dot(i.world - eye.xyz, viewForward.xyz);\n}\nfloat studio_uncut_distance_fragment(VertexOut i) : SV_Target {\n    return dot(i.world - eye.xyz, viewForward.xyz);\n}\nfloat4 studio_fullscreen_vertex(uint vid : SV_VertexID) : SV_Position {\n    return float4(vid == 1 ? 3.0 : -1.0, vid == 2 ? 3.0 : -1.0, 0.0, 1.0);\n}\nfloat3 pointAt(int2 p, float depth) {\n    return eye.xyz + (rayBase.xyz + (float)p.x * rayStepX.xyz + (float)p.y * rayStepY.xyz) * depth;\n}\nTexture2D<float> distanceTexture : register(t0);\nTexture2D<float> rawOcclusion : register(t1);\n\nfloat studio_occlusion_fragment(float4 position : SV_Position) : SV_Target {\n    uint w, h;\n    distanceTexture.GetDimensions(w, h);\n    int2 size = int2(w, h);\n    int2 p = int2(position.xy);\n    float d = distanceTexture.Load(int3(p, 0));\n    if (d <= 0.0) return 1.0;\n    float3 P = pointAt(p, d);\n    int2 x1 = min(p + int2(1, 0), size - 1), x0 = max(p - int2(1, 0), int2(0, 0));\n    int2 y1 = min(p + int2(0, 1), size - 1), y0 = max(p - int2(0, 1), int2(0, 0));\n    float dx1 = distanceTexture.Load(int3(x1, 0)), dx0 = distanceTexture.Load(int3(x0, 0));\n    float dy1 = distanceTexture.Load(int3(y1, 0)), dy0 = distanceTexture.Load(int3(y0, 0));\n    float3 X1 = dx1 > 0.0 ? pointAt(x1, dx1) - P : (float3)1e9, X0 = dx0 > 0.0 ? P - pointAt(x0, dx0) : (float3)1e9;\n    float3 Y1 = dy1 > 0.0 ? pointAt(y1, dy1) - P : (float3)1e9, Y0 = dy0 > 0.0 ? P - pointAt(y0, dy0) : (float3)1e9;\n    float3 X = length(X1) < length(X0) ? X1 : X0, Y = length(Y1) < length(Y0) ? Y1 : Y0;\n    if (length(X) > 1e8 || length(Y) > 1e8) return 1.0;\n    float3 N = normalize(cross(X, Y));\n    if (dot(N, eye.xyz - P) < 0.0) N = -N;\n    float reach = max(occlusion.x, 1e-5);\n    float pixel = d * length(rayStepX.xyz);\n    float reachPixels = clamp(reach / max(pixel, 1e-7), 2.0, 36.0);\n    if (occlusion.w > 0.5) return frac(reachPixels / 4.0);\n    static const int pattern[16] = { 0, 8, 2, 10, 12, 4, 14, 6, 3, 11, 1, 9, 15, 7, 13, 5 };\n    float turn = ((float)pattern[(p.y & 3) * 4 + (p.x & 3)] + 0.5) / 16.0;\n    float angle = turn * 6.2831853;\n    float occ = 0.0;\n    const int taps = 12;\n    [unroll] for (int k = 0; k < taps; k++) {\n        float t = ((float)k + frac(turn * 7.0 + 0.5)) / (float)taps;\n        float a = angle + (float)k * 2.3999632;\n        int2 q = clamp(p + int2(round(float2(cos(a), sin(a)) * reachPixels * t)), int2(0, 0), size - 1);\n        float dq = distanceTexture.Load(int3(q, 0));\n        if (dq <= 0.0) continue;\n        float3 v = pointAt(q, dq) - P;\n        float vv = dot(v, v);\n        float falloff = max(0.0, 1.0 - vv / (reach * reach));\n        occ += falloff * max(0.0, dot(v, N) - 0.03 * reach) / (vv + 0.02 * reach * reach) * reach;\n    }\n    return saturate(1.0 - occlusion.y * occ / (float)taps);\n}\n\nfloat studio_occlusion_blur_fragment(float4 position : SV_Position) : SV_Target {\n    uint w, h;\n    rawOcclusion.GetDimensions(w, h);\n    int2 size = int2(w, h);\n    int2 p = int2(position.xy);\n    float d = distanceTexture.Load(int3(p, 0));\n    if (d <= 0.0) return 1.0;\n    float3 P = pointAt(p, d);\n    float nearReach = max(occlusion.x, 1e-5) * 0.25;\n    float sum = 0.0, weight = 0.0;\n    [unroll] for (int y = -2; y <= 1; y++) {\n        [unroll] for (int x = -2; x <= 1; x++) {\n            int2 q = clamp(p + int2(x, y), int2(0, 0), size - 1);\n            float dq = distanceTexture.Load(int3(q, 0));\n            if (dq <= 0.0) continue;\n            float wq = saturate(1.0 - length(pointAt(q, dq) - P) / nearReach);\n            sum += rawOcclusion.Load(int3(q, 0)) * wq;\n            weight += wq;\n        }\n    }\n    return weight > 0.0 ? sum / weight : rawOcclusion.Load(int3(p, 0));\n}\n\nfloat occlusionAt(float2 pixel, float distance, float reach) {\n    uint w, h;\n    occlusionMap.GetDimensions(w, h);\n    int2 size = int2(w, h);\n    float2 at = pixel * 0.5 - 0.5;\n    int2 baseTexel = int2(floor(at));\n    float2 f = at - (float2)baseTexel;\n    float sum = 0.0, weight = 0.0, nearest = 1.0, nearestGap = 1e9;\n    [unroll] for (int y = 0; y <= 1; y++) {\n        [unroll] for (int x = 0; x <= 1; x++) {\n            int2 q = clamp(baseTexel + int2(x, y), int2(0, 0), size - 1);\n            float dq = occlusionDistances.Load(int3(q, 0));\n            float value = occlusionMap.Load(int3(q, 0));\n            float gap = dq > 0.0 ? abs(dq - distance) : 1e9;\n            if (gap < nearestGap) { nearestGap = gap; nearest = value; }\n            float wq = (x == 1 ? f.x : 1.0 - f.x) * (y == 1 ? f.y : 1.0 - f.y) * saturate(1.0 - gap / (reach * 0.25));\n            sum += value * wq;\n            weight += wq;\n        }\n    }\n    return weight > 1e-4 ? sum / weight : nearest;\n}\n\n// ---------------------------------------------------------------- the studio (also baked into the cube maps)\nfloat softbox(float3 d, float3 n, float halfWidth, float halfHeight, float intensity) {\n    float k = dot(d, n);\n    if (k <= 0.0) return 0.0;\n    float3 helper = abs(n.y) > 0.95 ? float3(0, 0, 1) : float3(0, 1, 0);\n    float3 u = normalize(cross(helper, n));\n    float3 v = cross(n, u);\n    float2 p = float2(dot(d, u), dot(d, v)) / k;\n    float2 q = abs(p) - float2(halfWidth, halfHeight);\n    float edge = max(q.x, q.y);\n    return intensity * (1.0 - smoothstep(-0.03, 0.03, edge));\n}\n\nfloat3 studioRadiance(float3 d, float room) {\n    float up = d.y;\n    float3 ceiling = float3(0.96, 0.97, 1.0), wall = float3(0.84, 0.86, 0.90), floorColor = float3(0.55, 0.53, 0.52);\n    float3 c = up >= 0.0 ? lerp(wall, ceiling, smoothstep(0.0, 0.85, up)) : lerp(wall, floorColor, smoothstep(0.0, 0.3, -up));\n    c *= room;\n    c += softbox(d, normalize(float3(-0.55, 0.62, 0.56)), 0.45, 0.32, 6.0) * float3(1.0, 0.97, 0.92);\n    c += softbox(d, normalize(float3(0.85, 0.22, 0.3)), 0.10, 0.62, 3.0);\n    c += softbox(d, float3(0.0, 1.0, 0.0), 0.55, 0.40, 2.2);\n    c += softbox(d, normalize(float3(0.35, 0.45, -0.85)), 0.40, 0.14, 2.4) * float3(0.80, 0.88, 1.0);\n    return c;\n}\n\nfloat3 cubeDirection(uint face, float2 uv) {\n    switch (face) {\n        case 0: return normalize(float3(1.0, -uv.y, -uv.x));\n        case 1: return normalize(float3(-1.0, -uv.y, uv.x));\n        case 2: return normalize(float3(uv.x, 1.0, uv.y));\n        case 3: return normalize(float3(uv.x, -1.0, -uv.y));\n        case 4: return normalize(float3(uv.x, -uv.y, 1.0));\n        default: return normalize(float3(-uv.x, -uv.y, -1.0));\n    }\n}\n\nfloat2 hammersley(uint i, uint count) {\n    uint bits = reversebits(i);\n    return float2((float)i / (float)count, (float)bits * 2.3283064365386963e-10);\n}\n\nfloat3 tangentToWorld(float3 hv, float3 n) {\n    float3 upv = abs(n.z) < 0.999 ? float3(0, 0, 1) : float3(1, 0, 0);\n    float3 tx = normalize(cross(upv, n));\n    float3 ty = cross(n, tx);\n    return tx * hv.x + ty * hv.y + n * hv.z;\n}\n\ncbuffer Bake : register(b2) { uint bakeLevel; uint bakeLevels; uint bakeSize; float bakeRoom; };\nRWTexture2DArray<float4> bakeTarget : register(u0);\n\n[numthreads(8, 8, 1)]\nvoid studio_bake_environment(uint3 gid : SV_DispatchThreadID) {\n    if (gid.x >= bakeSize || gid.y >= bakeSize) return;\n    float2 uv = ((float2)gid.xy + 0.5) / (float)bakeSize * 2.0 - 1.0;\n    float3 n = cubeDirection(gid.z, uv);\n    float roughness = (float)bakeLevel / (float)max(1u, bakeLevels - 1u);\n    float3 total = 0.0;\n    if (bakeLevel == 0u) {\n        total = studioRadiance(n, bakeRoom);\n    } else {\n        float alpha = roughness * roughness;\n        float weight = 0.0;\n        const uint samples = 192u;\n        [loop] for (uint i = 0u; i < samples; i++) {\n            float2 xi = hammersley(i, samples);\n            float phi = 2.0 * PI * xi.x;\n            float cosTheta = sqrt((1.0 - xi.y) / (1.0 + (alpha * alpha - 1.0) * xi.y));\n            float sinTheta = sqrt(1.0 - cosTheta * cosTheta);\n            float3 hv = tangentToWorld(float3(cos(phi) * sinTheta, sin(phi) * sinTheta, cosTheta), n);\n            float3 l = normalize(2.0 * dot(n, hv) * hv - n);\n            float nl = dot(n, l);\n            if (nl > 0.0) { total += studioRadiance(l, bakeRoom) * nl; weight += nl; }\n        }\n        total /= max(weight, 1e-4);\n    }\n    bakeTarget[gid] = float4(total, 1.0);\n}\n\n[numthreads(8, 8, 1)]\nvoid studio_bake_irradiance(uint3 gid : SV_DispatchThreadID) {\n    if (gid.x >= bakeSize || gid.y >= bakeSize) return;\n    float2 uv = ((float2)gid.xy + 0.5) / (float)bakeSize * 2.0 - 1.0;\n    float3 n = cubeDirection(gid.z, uv);\n    float3 total = 0.0;\n    const uint samples = 512u;\n    [loop] for (uint i = 0u; i < samples; i++) {\n        float2 xi = hammersley(i, samples);\n        float phi = 2.0 * PI * xi.x;\n        float cosTheta = sqrt(1.0 - xi.y), sinTheta = sqrt(xi.y);\n        float3 l = tangentToWorld(float3(cos(phi) * sinTheta, sin(phi) * sinTheta, cosTheta), n);\n        total += studioRadiance(l, bakeRoom);\n    }\n    bakeTarget[gid] = float4(total / (float)samples, 1.0);\n}\n\n// ---------------------------------------------------------------- shading\nfloat D_GGX(float alpha, float nh) { float a2 = alpha * alpha; float d = nh * nh * (a2 - 1.0) + 1.0; return INV_PI * a2 / (d * d); }\nfloat V_Smith(float alpha, float nl, float nv) {\n    float a2 = alpha * alpha;\n    float gv = nl * sqrt(a2 + (1.0 - a2) * nv * nv), gl = nv * sqrt(a2 + (1.0 - a2) * nl * nl);\n    return 0.5 / max(gv + gl, 1e-6);\n}\nfloat3 F_Schlick(float3 f0, float vh) { float f = exp2((-5.55473 * vh - 6.98316) * vh); return f0 * (1.0 - f) + f; }\nfloat3 specularGGX(float3 l, float3 v, float3 n, float3 f0, float roughness) {\n    float alpha = roughness * roughness;\n    float3 hv = normalize(l + v);\n    float nl = saturate(dot(n, l)), nv = saturate(dot(n, v)), nh = saturate(dot(n, hv)), vh = saturate(dot(v, hv));\n    return F_Schlick(f0, vh) * (V_Smith(alpha, nl, nv) * D_GGX(alpha, nh));\n}\nfloat3 environmentBRDF(float3 f0, float roughness, float nv) {\n    const float4 c0 = float4(-1.0, -0.0275, -0.572, 0.022), c1 = float4(1.0, 0.0425, 1.04, -0.04);\n    float4 r = roughness * c0 + c1;\n    float a004 = min(r.x * r.x, exp2(-9.28 * nv)) * r.x + r.y;\n    float2 ab = float2(-1.04, 1.04) * a004 + r.zw;\n    return f0 * ab.x + ab.y;\n}\nfloat3 neutralToneMap(float3 color) {\n    const float startCompression = 0.8 - 0.04, desaturation = 0.15;\n    float x = min(color.r, min(color.g, color.b));\n    float offset = x < 0.08 ? x - 6.25 * x * x : 0.04;\n    color -= offset;\n    float peak = max(color.r, max(color.g, color.b));\n    if (peak < startCompression) return color;\n    float d = 1.0 - startCompression;\n    float newPeak = 1.0 - d * d / (peak + d - startCompression);\n    color *= newPeak / peak;\n    float g = 1.0 - 1.0 / (desaturation * (peak - newPeak) + 1.0);\n    return lerp(color, (float3)newPeak, g);\n}\n// Blender's AgX as three.js ships it, with Blender's look step. The matrices are Metal's column lists, so the\n// products are mul(v, M).\nfloat3 agxToneMap(float3 color, float power, float saturation) {\n    const float3x3 sRGBToRec2020 = float3x3(float3(0.6274, 0.0691, 0.0164), float3(0.3293, 0.9195, 0.0880), float3(0.0433, 0.0113, 0.8956));\n    const float3x3 rec2020ToSRGB = float3x3(float3(1.6605, -0.1246, -0.0182), float3(-0.5876, 1.1329, -0.1006), float3(-0.0728, -0.0083, 1.1187));\n    const float3x3 inset = float3x3(float3(0.856627153315983, 0.137318972929847, 0.11189821299995),\n                                    float3(0.0951212405381588, 0.761241990602591, 0.0767994186031903),\n                                    float3(0.0482516061458583, 0.101439036467562, 0.811302368396859));\n    const float3x3 outset = float3x3(float3(1.1271005818144368, -0.1413297634984383, -0.14132976349843826),\n                                     float3(-0.11060664309660323, 1.157823702216272, -0.11060664309660294),\n                                     float3(-0.016493938717834573, -0.016493938717834257, 1.2519364065950405));\n    const float minEv = -12.47393, maxEv = 4.026069;\n    float3 x = mul(mul(color, sRGBToRec2020), inset);\n    x = clamp((log2(max(x, 1e-10)) - minEv) / (maxEv - minEv), 0.0, 1.0);\n    float3 x2 = x * x, x4 = x2 * x2;\n    x = 15.5 * x4 * x2 - 40.14 * x4 * x + 31.96 * x4 - 6.868 * x2 * x + 0.4298 * x2 + 0.1191 * x - 0.00232;\n    float luma = dot(x, float3(0.2126, 0.7152, 0.0722));\n    x = pow(max(x, 0.0), power);\n    x = luma + saturation * (x - luma);\n    x = pow(max(mul(x, outset), 0.0), 2.2);\n    return clamp(mul(x, rec2020ToSRGB), 0.0, 1.0);\n}\nfloat3 toneMap(float3 color) {\n    return grade.x > 0.5 ? agxToneMap(color, grade.y, grade.z) : neutral