olor = base.rgb * (1.0 - metalness);\n    float3 f0 = lerp((float3)0.04, base.rgb, metalness);\n\n    float3 v = normalize(eye.xyz - i.world);\n    float nv = saturate(dot(n, v));\n    float3 keyDir = key.xyz, rimDir = rim.xyz;\n    float visibility = shadowVisibility(i.world, n, shadow.w * 0.6);\n    if (rim.w > 1.5) return float4(ambientOcclusion, ambientOcclusion, ambientOcclusion, 1.0);\n    if (rim.w > 0.5) return float4(visibility, visibility, visibility, 1.0);\n    if (o.coat.w > 0.5) visibility = 1.0;\n    float nlKey = saturate(dot(n, keyDir)), nlRim = saturate(dot(n, rimDir));\n    float keyShade = lerp(0.55, 1.0, visibility) * lerp(1.0, ambientOcclusion, 0.3);\n    float3 color = keyColor.rgb * nlKey * keyShade * (diffuseColor * INV_PI + specularGGX(keyDir, v, n, f0, roughness));\n    color += rimColor.rgb * nlRim * (diffuseColor * INV_PI + specularGGX(rimDir, v, n, f0, roughness));\n\n    float environmentStrength = environment.z;\n    float3 r = reflect(-v, n);\n    const float maxMip = 6.0;\n    float3 prefiltered = environmentMap.SampleLevel(environmentSampler, turnIntoStudio(r), roughness * maxMip).rgb;\n    float3 ambient = irradianceMap.SampleLevel(environmentSampler, turnIntoStudio(n), 0).rgb;\n    float occ = lerp(0.6, 1.0, visibility) * lerp(1.0, ambientOcclusion, 0.75);\n    color += (ambient * diffuseColor * 0.72 * lerp(0.6, 1.0, visibility) * ambientOcclusion + prefiltered * environmentBRDF(f0, roughness, nv) * occ)\n             * environmentStrength;\n\n    float sheen = o.coat.z;\n    if (sheen > 0.0) color += sheen * lerp(base.rgb, (float3)1.0, 0.5) * pow(1.0 - nv, 3.0) * 0.5 * environmentStrength;\n\n    float coat = o.coat.x;\n    if (coat > 0.0) {\n        float coatRoughness = max(o.coat.y, 0.045);\n        float fresnel = F_Schlick((float3)0.04, nv).x;\n        float3 coatSpecular = keyColor.rgb * nlKey * keyShade * specularGGX(keyDir, v, n, (float3)0.04, coatRoughness)\n            + environmentMap.SampleLevel(environmentSampler, turnIntoStudio(r), coatRoughness * maxMip).rgb\n              * environmentBRDF((float3)0.04, coatRoughness, nv) * environmentStrength * occ;\n        color = color * (1.0 - coat * fresnel) + coat * coatSpecular;\n    }\n    float glow = max(o.emissive.r, max(o.emissive.g, o.emissive.b));\n    if (glow > 0.0) {\n        float3 lamp = o.emissive.rgb / glow * min(glow, 0.9);\n        color = max(color * (1.0 - saturate(glow)), lamp) + lamp * pow(nv, 3.0) * 0.18;\n    }\n\n    float alpha = base.a * o.surface.z;\n    if (o.coat.w > 0.5) {\n        float fresnel = F_Schlick((float3)0.04, nv).x;\n        float3 reflection = prefiltered * environmentStrength;\n        color = lerp(color, reflection, fresnel);\n        float highlight = dot(color, float3(0.2126, 0.7152, 0.0722));\n        alpha = clamp(max(lerp(alpha, 1.0, fresnel), saturate(highlight - 0.75) * 0.8), 0.0, 1.0);\n    }\n    color = glow > 0.0 ? lerp(toneMap(color * environment.w), min(color, 1.0), saturate(glow))\n                       : toneMap(color * environment.w);\n    return float4(sRGBFromLinear(color), alpha);\n}\n\n// ---------------------------------------------------------------- the ground: only the object's shadow\nstruct GroundOut { float4 position : SV_Position; float3 world : TEXCOORD0; };\n\nGroundOut studio_ground_vertex(uint vid : SV_VertexID) {\n    float2 corner = float2((vid & 1u) ? 1.0 : -1.0, (vid >> 1u) ? 1.0 : -1.0);\n    float3 world = float3(ground.y + corner.x * ground.w, ground.x, ground.z + corner.y * ground.w);\n    GroundOut r;\n    r.position = mul(viewProjection, float4(world, 1.0));\n    r.world = world;\n    return r;\n}\n\nfloat4 studio_ground_fragment(GroundOut i) : SV_Target {\n    float4 clip = mul(lightViewProjection, float4(i.world + float3(0.0, shadow.z, 0.0), 1.0));\n    float3 ndc = clip.xyz / clip.w;\n    float2 uv = float2(ndc.x * 0.5 + 0.5, 0.5 - ndc.y * 0.5);\n    if (any(uv < 0.0) || any(uv > 1.0) || ndc.z > 1.0) discard;\n    float reference = ndc.z - shadow.y;\n    float radius = ground.w / 1.9;\n    float shade = 0.0;\n    [unroll] for (int k = 0; k < 12; k++) {\n        float depth = shadowMap.SampleLevel(pointClamp, uv + SHADOW_DISK[k] * shadow.x * shadow.w * 2.0, 0);\n        if (depth < reference) {\n            float height = (reference - depth) * key.w;\n            shade += 1.0 - smoothstep(radius * 0.05, radius * 0.7, height);\n        }\n    }\n    shade /= 12.0;\n    float distanceOut = length(i.world.xz - float2(ground.y, ground.z)) / ground.w;\n    float fade = 1.0 - smoothstep(0.55, 1.0, distanceOut);\n    float alpha = shade * groundColor.a * fade;\n    return float4(sRGBFromLinear(groundColor.rgb), alpha);\n}";

	public const string Overlay = "struct Capsule { float2 a; float2 b; float radius; float haloWidth; float2 pad; float4 color; float4 halo; };\nstruct Sheet { float2 center; float2 halfSize; float angle; float cornerRadius; float2 pad; float4 color; };\nStructuredBuffer<Capsule> capsules : register(t0);\nStructuredBuffer<Sheet> sheets : register(t1);\ncbuffer Target : register(b0) { float2 targetSize; uint sheetIndex; uint targetPad; };\nstruct OverlayOut { float4 position : SV_Position; nointerpolation uint instance : INSTANCE; };\n\nOverlayOut stage_overlay_vertex(uint vid : SV_VertexID, uint iid : SV_InstanceID) {\n    Capsule c = capsules[iid];\n    float pad = c.radius + c.haloWidth + 1.5;\n    float2 low = min(c.a, c.b) - pad, high = max(c.a, c.b) + pad;\n    float2 p = float2((vid & 1u) ? high.x : low.x, (vid >> 1u) ? high.y : low.y);\n    OverlayOut r;\n    r.position = float4(p.x / targetSize.x * 2.0 - 1.0, 1.0 - p.y / targetSize.y * 2.0, 0.0, 1.0);\n    r.instance = iid;\n    return r;\n}\n\nfloat4 stage_overlay_fragment(OverlayOut i) : SV_Target {\n    Capsule c = capsules[i.instance];\n    float2 p = i.position.xy, ab = c.b - c.a;\n    float l2 = dot(ab, ab);\n    float t = l2 > 0.0 ? clamp(dot(p - c.a, ab) / l2, 0.0, 1.0) : 0.0;\n    float d = distance(p, c.a + ab * t);\n    float core = saturate(c.radius - d + 0.5);\n    float glow = c.haloWidth > 0.0 ? saturate(c.radius + c.haloWidth - d + 0.5) : 0.0;\n    float4 inner = c.color * core;\n    return inner + c.halo * glow * (1.0 - inner.a);\n}\n\nOverlayOut stage_sheet_vertex(uint vid : SV_VertexID) {\n    Sheet s = sheets[sheetIndex];\n    float c = cos(s.angle), n = sin(s.angle);\n    float2 corner = float2((vid & 1u) ? 1.0 : -1.0, (vid >> 1u) ? 1.0 : -1.0) * (s.halfSize + 1.5);\n    float2 p = s.center + float2(corner.x * c - corner.y * n, corner.x * n + corner.y * c);\n    OverlayOut r;\n    r.position = float4(p.x / targetSize.x * 2.0 - 1.0, 1.0 - p.y / targetSize.y * 2.0, 0.0, 1.0);\n    r.instance